<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ElMessage, ElMessageBox } from 'element-plus'; import AppLayout from '@/layouts/AppLayout.vue'; import FileUpload from '@/components/FileUpload.vue'; import DocumentStatus from '@/components/DocumentStatus.vue'; import * as api from '@/api/documents'; import type { DocumentItem } from '@/types'
const route=useRoute(); const router=useRouter(); const id=Number(route.params.id); const docs=ref<DocumentItem[]>([]); const loading=ref(false)
async function load(){loading.value=true; try{docs.value=await api.listDocuments(id)}catch{docs.value=[]}finally{loading.value=false}}
async function remove(item:DocumentItem){await ElMessageBox.confirm(`确定删除“${item.fileName}”吗？`,'删除文档',{type:'warning'}); try{await api.deleteDocument(item.id); ElMessage.success('文档已删除'); load()}catch{ElMessage.error('删除失败')}}
async function reindex(item:DocumentItem){try{await api.reindexDocument(item.id); ElMessage.success('已重新进入处理队列'); load()}catch{ElMessage.error('重新索引失败')}}
function uploaded(){load()}; onMounted(load)
</script>
<template><AppLayout><div class="detail-hero compact-hero"><div><button class="back-link" @click="router.push(`/knowledge/${id}`)">← 返回知识库</button><p class="eyebrow">DOCUMENTS</p><h1>文档管理</h1><p>上传、处理并维护当前知识库的资料。</p></div><button class="ghost-button" @click="router.push(`/knowledge/${id}/chat`)">✦ 进入问答</button></div><FileUpload :knowledge-base-id="id" @uploaded="uploaded"/><section class="panel document-panel"><div class="panel-heading"><div><h2>已上传文档</h2><p>处理状态会在后台异步更新</p></div><span class="result-count">{{ docs.length }} 份</span></div><div v-if="docs.length" class="document-list"><div v-for="doc in docs" :key="doc.id" class="document-row"><div class="file-icon">{{ doc.fileType.toUpperCase() }}</div><div class="doc-info"><strong>{{ doc.fileName }}</strong><small>{{ (doc.fileSize/1024/1024).toFixed(2) }} MB · {{ doc.pageCount || '-' }} 页</small></div><DocumentStatus :status="doc.status" :error-message="doc.errorMessage"/><div class="doc-summary">{{ doc.summary || '等待处理完成后生成摘要' }}</div><div class="doc-actions"><button v-if="doc.status === 'FAILED'" @click="reindex(doc)">重试</button><button @click="remove(doc)">删除</button></div></div></div><div v-else class="table-empty">暂无文档，点击上方区域上传。</div></section></AppLayout></template>

